CREATE TABLE public.credit_sites (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    asset_type_id uuid NOT NULL,
    name text NOT NULL,
    display_name text NOT NULL,
    website_url text,
    attribution_format text,
    description text,
    logo_url text,
    sort_order integer DEFAULT 0 NOT NULL,
