--

CREATE VIEW public.tool_usage_events_enriched WITH (security_invoker='true') AS
 SELECT e.id,
    e.user_id,
    e.auth_uid,
    e.tool_id,
    e.tool_session_id,
    e.app_session_id,
    e.event_type,
    e.event_timestamp,
    e.event_data,
    e.created_at,
    e.is_synced,
    e.last_synced_at,
    s.public_ip,
    s.country,
    s.region,
    s.city
   FROM (public.tool_usage_events e
     LEFT JOIN public.app_sessions s ON ((e.app_session_id = s.id)));


